+                quester("<redacted>", "Hunter", 2, "Coldridge Valley"),
+                quester("<redacted>", "Warlock", None, None),
+            ],
+        },
+        {
+            "guild": "<redacted>",
+            "faction": "Horde",
+            "questers": [
+                quester("<redacted>", "Paladin", 4, "Sunstrider Isle"),
+                quester("<redacted>", "Priest", 4, "Deathknell"),
+                quester("<redacted>", "Hunter", 3, "Camp Narache"),
