+    EXPECT_EQ(p.stepIndex, 1u);
+    EXPECT_EQ(p.timeoutRewinds, 0u);
+    EXPECT_FALSE(DungeonEventExecutor::BeginsHookAttempt(p));
+
+    EXPECT_EQ(DungeonEventExecutor::Advance(*e, p, StepResult::WaitingForRecovery,
