+    document: { createElement: () => mockCanvas },
+    window: null,
+    globalThis: null,
+    Image: function () { this.onload = null; this.onerror = null; this.src = ''; }
+  };
+  ctx.window = ctx;
+  ctx.globalThis = ctx;
