+  const townNpc = { id: 'guide', name: 'Station Guide', x: 8, y: 7, map: 'PistonTown' };
+  assert.equal(
+    WorldArt.shouldRenderCharacter(townNpc, { map: town }),
+    true,
+    'NPC on the same map should be rendered'
